using P=std::vector<int>;int mod;
int norm(long long a){a%=mod;if(a<0)a+=mod;return a;}int inv(int a){int b=mod-2,r=1;for(;b;b>>=1,a=norm(a*a))if(b&1)r=norm(r*a);return r;}
void trim(P&a){while(!a.empty()&&!a.back())a.pop_back();}P con(int a){return a?P{norm(a)}:P{};}P add(P a,const P&b,int scale=1){a.resize(std::max(a.size(),b.size()));for(int i=0;i<(int)b.size();i++)a[i]=norm(a[i]+scale*b[i]);trim(a);return a;}P mul(const P&a,const P&b){if(a.empty()||b.empty())return{};P c(a.size()+b.size()-1);for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)b.size();j++)c[i+j]=norm(c[i+j]+a[i]*b[j]);trim(c);return c;}P sc(P a,int s){for(int&x:a)x=norm(x*s);trim(a);return a;}P rem(P a,const P&b){if(b.empty())throw 1;int v=inv(b.back());while(a.size()>=b.size()&&!a.empty()){int d=a.size()-b.size(),c=norm(a.back()*v);for(int i=0;i<(int)b.size();i++)a[i+d]=norm(a[i+d]-c*b[i]);trim(a);}return a;}P gcd(P a,P b){while(!b.empty()){P c=rem(a,b);a=b;b=c;}return a.empty()?a:sc(a,inv(a.back()));}int ev(const P&a,int x){int y=0;for(int i=(int)a.size()-1;i>=0;i--)y=norm(y*x+a[i]);return y;}
struct R{P a,b;};int ls,lh;P zz{0,1};R plus(R a,R b,int s=1){return{add(a.a,b.a,s),add(a.b,b.b,s)};}R scale(R a,int s){return{sc(a.a,s),sc(a.b,s)};}R times(R a,R b){P bd=mul(a.b,b.b);return{add(mul(a.a,b.a),mul(zz,bd),-lh),add(add(mul(a.a,b.b),mul(a.b,b.a)),bd,-ls)};}R scalar(P a){return{a,{}};}R one(){return scalar({1});}
int root(int a){for(int x=0;x<mod;x++)if(x*x%mod==a)return x;return -1;}std::vector<int> roots(int s,int p){std::vector<int>v;for(int x=0;x<mod;x++)if(norm(x*x+s*x+p)==0)v.push_back(x);return v;}
std::string arr(const P&a){std::string s="[";for(int i=0;i<(int)a.size();i++){if(i)s+=",";s+=std::to_string(a[i]);}return s+"]";}
