  int sigma=root(z);if(sigma<0)continue;bad=false;for(int ee:es)if(root(ee)<0)bad=true;if(bad)continue;int tau=norm(k*inv(sigma));P C[4],A[4],B[4],F[8];for(int i=0;i<4;i++){C[i]={1};for(int j=0;j<4;j++)if(j!=i)C[i]=mul(C[i],{norm(-e[i][j]),1});A[i]=sc(C[i],a[i]);}
  P RY=add(mul({p,1},{p,1}),{0,z},-1);for(int i=1;i<4;i++){P num=add(sc(add(C[0],A[i],-1),sigma),sc(mul(RY,{norm(-e[0][i]),1}),norm(tau*beta[i])));num.resize(4);P quo(3);for(int l=3;l>=1;l--){int cc=l<(int)num.size()?num[l]:0;quo[l-1]=cc;num[l]=0;num[l-1]=norm(num[l-1]-p*cc);}if(num[0])throw 3;B[i]=quo;}
  for(int i=0;i<4;i++)for(int sg=0;sg<2;sg++){F[2*i+sg]=P(7);for(int l=0;l<4;l++)F[2*i+sg][2*l]=norm((sg?-1:1)*A[i][l]);for(int l=0;l<(int)B[i].size();l++)F[2*i+sg][2*l+1]=B[i][l];}
