  int counts[8]={};for(int j=0;j<28;j++){int mask=0;for(int i=0;i<8;i++)if(ev(F[i],nodes[j])==word[j]){mask|=1<<i;counts[i]++;}if(mask!=masks[j])throw 5;}for(int v:counts)if(v!=14)throw 6;hits++;if(!first)out<<",";first=false;out<<"{\"b\":"<<b<<",\"c\":"<<c<<",\"q\":"<<q<<",\"h\":"<<h<<",\"z\":"<<z<<",\"sigma\":"<<sigma<<",\"nodes\":"<<arr(nodes)<<",\"word\":"<<arr(word)<<",\"masks\":"<<arr(masks)<<",\"polynomials\":[";for(int i=0;i<8;i++){if(i)out<<",";out<<arr(F[i]);}out<<"]}";out.flush();
